% 多重网格法中的相关函数
function jie = V_xunhuan(jie,f,h)
% 递归v循环
%预先平滑
jie = smoothing(jie,f,h);
%算残差
r_old = cancha(jie,f,h);
%限制
r_new = xianzhi(r_old);
%算误差
e = zeros(size(r_new));
%如果网格已经达到最粗，停止递归，否则继续递归
if length(e)-1 == 2
e = smoothing(e,r_new,2h);
else
e = V_xunhuan(e,r_new,2h);
end
% 修正
jie = jie + yantuo(e);
%后光滑
jie = smoothing(jie,f,h);
end

function res = smoothing(phi,f,h)
N = size(phi, 1) - 1;
res = phi;
for i = 2:N
for j = 2:N
res(i, j) = (phi(i+1, j)+res(i-1, j)+phi(i, j+1)+res(i, j-1)+h^2f(i, j))/4;
end
end
end

function res = cancha(phi,f,h)
N = size(phi, 1) - 1;
res = zeros(N+1, N+1);
res(2:N, 2:N) = f(2:N, 2:N)-(phi(1:N-1, 2:N)-2phi(2:N, 2:N)+phi(3:N+1, 2:N)+phi(2:N, 1:N-1)-2phi(2:N, 2:N)+phi(2:N, 3:N+1))/h^2;
end

function r_xi = xianzhi(r_cu)
N = (size(r_cu, 1) - 1) / 2;
r_xi = zeros(N+1, N+1);
for i = 2:N
for j = 2:N
r_xi(i, j) = 1/4(r_cu(2i-1, 2j-1) + r_cu(2i-1, 2j+1) + r_cu(2i+1, 2j-1) + r_cu(2i+1, 2j+1));
end
end
end

function e_xiwang = yantuo(e_cuwang)
